const inputItems = $input.all();

const results = [];

for (const item of inputItems) {
  const events = item.json?._embedded?.events ?? [];

  for (const event of events) {
    const images = Array.isArray(event.images) ? event.images : [];

    // Prefer non-fallback, highest resolution image
    const validImages = images
      .filter(img => img?.url && img?.fallback !== true)
      .sort((a, b) => {
        const aPixels = (a.width || 0) * (a.height || 0);
        const bPixels = (b.width || 0) * (b.height || 0);
        return bPixels - aPixels;
      });

    const bestImage = validImages[0]?.url || null;

    const venue = event?._embedded?.venues?.[0];

    results.push({
      json: {
        source: "ticketmaster",
        source_event_id: event.id || null,

        event_name: event.name || null,

        // Start date/time
        event_date: event?.dates?.start?.localDate || null,
        event_time: event?.dates?.start?.localTime || null,

        // End date
        end_date: event?.dates?.end?.localDate || "null",

        // Timezone
        timezone: event?.dates?.timezone || null,

        // Venue
        venue_name: venue?.name || null,

        // Venue coordinates
        venue_latitude: venue?.location?.latitude
          ? Number(venue.location.latitude)
          : null,

        venue_longitude: venue?.location?.longitude
          ? Number(venue.location.longitude)
          : null,

        description:
          event.info ||
          event.description ||
          null,

        ticket_link: event.url || null,

        image_url: bestImage,

        status: event?.dates?.status?.code || null,

        ticketmaster_url: event.url || null,

        raw_ticketmaster_event: event
      }
    });
  }
}

return results;

