const events = $input.all();

const firstEvent = events[0]?.json || {};

const city = firstEvent.city || '';
const country = firstEvent.country || '';

let content = `KYNCT – Ticketmaster Imported Events
====================================

IMPORT SUMMARY
--------------

Source: Ticketmaster
Location: ${city}, ${country}
Events imported: ${events.length}

`;

events.forEach((item, index) => {
  const e = item.json;

  content += `EVENT ${index + 1}
--------------------

Event Name: ${e.event_name || ''}
Date: ${e.event_date || ''}
Time: ${e.event_time || ''}
Timezone: ${e.timezone || ''}
End Date: ${e.end_date || ''}
Venue Name: ${e.venue || ''}
Venue Latitude: ${e.venue_latitude ?? ''}
Venue Longitude: ${e.venue_longitude ?? ''}
City: ${e.city || ''}
Country: ${e.country || ''}

Description:
${e.description || ''}

Ticket Link:
${e.ticket_link || ''}

Image URL:
${e.image_url || ''}

Source: ${e.source || ''}
Source Event ID: ${e.source_event_id || ''}

----------------------------------------

`;
});

return [
  {
    json: {
      title: 'KYNCT – Ticketmaster Imported Events',
      document_content: content
    }
  }
];

// =====================================================
// 1. EXISTING GOOGLE SHEET EVENTS
// =====================================================

const existingItems = $input.all();


// =====================================================
// 2. CURRENT TICKETMASTER EVENTS
//    Use Limit node output, not all 319 events
// =====================================================

const currentItems = $('Limit').all();


// =====================================================
// 3. EXISTING EVENTS MAP
//    source_event_id is the ONLY matching key
// =====================================================

const existingMap = new Map();

for (const item of existingItems) {

  const existing = item.json || {};

  const sourceEventId = String(
    existing.source_event_id ?? ''
  ).trim();

  if (sourceEventId !== '') {
    existingMap.set(sourceEventId, existing);
  }
}


// =====================================================
// 4. FIELDS TO COMPARE
//    These match the fields stored in Google Sheet
// =====================================================

const compareFields = [
  'event_name',
  'description',
  'event_date',
  'event_time',
  'end_date',
  'venue',
  'venue_latitude',
  'venue_longitude',
  'city',
  'country',
  'ticket_link',
  'image_url',
  'timezone',
  'source'
];


// =====================================================
// 5. NORMALIZE VALUES
// =====================================================

function normalize(field, value) {

  // ---------------------------------------------------
  // null / undefined / empty / "null" = same
  // ---------------------------------------------------

  if (
    value === null ||
    value === undefined ||
    value === '' ||
    String(value).trim().toLowerCase() === 'null'
  ) {
    return '';
  }

  let v = String(value).trim();


  // ---------------------------------------------------
  // Normalize spaces
  // ---------------------------------------------------

  v = v.replace(/\s+/g, ' ');


  // ---------------------------------------------------
  // Normalize dates
  // ---------------------------------------------------

  if (
    field === 'event_date' ||
    field === 'end_date'
  ) {
    v = v.replace('T', ' ');
    v = v.replace(/Z$/, '');
    v = v.trim();
  }


  // ---------------------------------------------------
  // Normalize event time
  //
  // Examples:
  // 09:30:00 → 09:30:00
  // 9:30:00  → 09:30:00
  // 09:30    → 09:30:00
  // 9:30     → 09:30:00
  // ---------------------------------------------------

  if (field === 'event_time') {

    const match = v.match(
      /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/
    );

    if (match) {

      const hours = match[1].padStart(2, '0');
      const minutes = match[2];
      const seconds = match[3] || '00';

      v = `${hours}:${minutes}:${seconds}`;
    }
  }


  // ---------------------------------------------------
  // Normalize URLs
  // ---------------------------------------------------

  if (
    field === 'ticket_link' ||
    field === 'image_url'
  ) {
    v = v.replace(/\/$/, '');
  }


  // ---------------------------------------------------
  // Normalize coordinates
  // ---------------------------------------------------

  if (
    field === 'venue_latitude' ||
    field === 'venue_longitude'
  ) {

    const numberValue = Number(v);

    if (!Number.isNaN(numberValue)) {
      return numberValue.toFixed(6);
    }
  }


  return v;
}


// =====================================================
// 6. COUNTERS
// =====================================================

let newCount = 0;
let updatedCount = 0;
let unchangedCount = 0;


// =====================================================
// 7. ONLY NEW + UPDATED EVENTS ARE RETURNED
// =====================================================

const results = [];


// =====================================================
// 8. COMPARE CURRENT EVENTS WITH GOOGLE SHEET
// =====================================================

for (const item of currentItems) {

  const current = item.json || {};


  // ---------------------------------------------------
  // Current source_event_id
  // ---------------------------------------------------

  const sourceEventId = String(
    current.source_event_id ?? ''
  ).trim();


  // ---------------------------------------------------
  // Match ONLY by source_event_id
  // ---------------------------------------------------

  const existing = existingMap.get(sourceEventId);


  // ===================================================
  // CASE 1: NEW EVENT
  // ===================================================

  if (!existing) {

    newCount++;

    results.push({
      json: {
        ...current,

        // Get city/country from raw Ticketmaster data
        city:
          current.city ??
          current.raw_ticketmaster_event?._embedded
            ?.venues?.[0]
            ?.city?.name ??
          null,

        country:
          current.country ??
          current.raw_ticketmaster_event?._embedded
            ?.venues?.[0]
            ?.country?.name ??
          null,

        change_type: 'new',

        differences: {}
      }
    });

    continue;
  }


  // ===================================================
  // CASE 2: EXISTING EVENT
  // ===================================================

  const differences = {};


  // ---------------------------------------------------
  // Build current values in the SAME structure
  // as Google Sheet
  // ---------------------------------------------------

  const currentComparable = {

    event_name: current.event_name,

    description: current.description,

    event_date: current.event_date,

    event_time: current.event_time,

    end_date: current.end_date,

    venue: current.venue_name,

    venue_latitude: current.venue_latitude,

    venue_longitude: current.venue_longitude,

    city:
      current.city ??
      current.raw_ticketmaster_event?._embedded
        ?.venues?.[0]
        ?.city?.name ??
      null,

    country:
      current.country ??
      current.raw_ticketmaster_event?._embedded
        ?.venues?.[0]
        ?.country?.name ??
      null,

    ticket_link: current.ticket_link,

    image_url: current.image_url,

    timezone: current.timezone,

    source: current.source
  };


  // ===================================================
  // COMPARE EACH FIELD
  // ===================================================

  for (const field of compareFields) {

    const currentValue = normalize(
      field,
      currentComparable[field]
    );

    const sheetValue = normalize(
      field,
      existing[field]
    );


    // -------------------------------------------------
    // Actual change detected
    // -------------------------------------------------

    if (currentValue !== sheetValue) {

      differences[field] = {
        current: currentValue,
        sheet: sheetValue
      };
    }
  }


  // ===================================================
  // CASE 2A: UPDATED
  // ===================================================

  if (Object.keys(differences).length > 0) {

    updatedCount++;

    results.push({
      json: {
        ...currentComparable,
        ...current,

        // Keep correct Sheet values
        venue:
          current.venue_name,

        city:
          currentComparable.city,

        country:
          currentComparable.country,

        change_type: 'updated',

        differences
      }
    });

  }


  // ===================================================
  // CASE 2B: UNCHANGED
  // ===================================================
  //
  // Do NOT return unchanged events.
  // They will stop the workflow if nothing else changed.
  //

  else {

    unchangedCount++;
  }
}


// =====================================================
// 9. RETURN ONLY NEW + UPDATED EVENTS
// =====================================================

return results.map(item => ({
  json: {

    ...item.json,

    new_count: newCount,

    updated_count: updatedCount,

    unchanged_count: unchangedCount,

    should_create_doc:
      newCount > 0 ||
      updatedCount > 0
  }
}));
